<script setup lang="ts">
import { onMounted, ref, watch } from 'vue';
import { fetchTitle } from '@/entities/title/title.api';
import { fetchGenres } from '@/entities/genre/genre.api';
import AdminR2PickerModal from './AdminR2PickerModal.vue';
import {
  adminSearchTitles,
  createEpisode,
  deleteEpisode,
  getAdminEpisode,
  groupTitle,
  reorderEpisodes,
  reorderSeasons,
  ungroupTitle,
  updateEpisode,
  updateTitle,
  uploadPhoto,
  type AdminTitleListItem,
  type CreateEpisodeInput,
} from '@/entities/admin/admin.api';
import type { EpisodeItem, Genre, TitleDetail } from '@/shared/api/types';

const props = defineProps<{ titleId: number }>();

const title = ref<TitleDetail | null>(null);
const episodes = ref<EpisodeItem[]>([]);
const genres = ref<Genre[]>([]);
const error = ref<string | null>(null);
const busy = ref(false);

const activeTab = ref<'episodes' | 'seasons'>('episodes');
const showEditModal = ref(false);

type AltKind = 'original' | 'english' | 'ukrainian' | 'other';
const meta = ref({
  displayName: '',
  seasonNumber: '1',
  seasonLabel: '',
  description: '',
  originalReleaseDate: '',
  episodesCount: '',
  episodesOpen: false,
  visible: true,
  posterUrl: '',
  genreIds: [] as number[],
  names: [] as { kind: AltKind; name: string }[],
});
const metaOk = ref(false);
const metaError = ref<string | null>(null);

// Add-episode form
const epNumber = ref('');
const epLabel = ref('');
const streamUrl = ref('');
const videoUrl = ref('');
const tgFileId = ref('');
const previewUrl = ref('');
const epError = ref<string | null>(null);

// Grouping
const groupQuery = ref('');
const groupResults = ref<AdminTitleListItem[]>([]);
const groupError = ref<string | null>(null);

// Picker
const showPicker = ref(false);
const pickerType = ref<'photo' | 'video'>('photo');
const pickerTarget = ref<'poster' | 'add-preview' | 'edit-preview' | 'add-stream' | 'edit-stream'>('poster');

function openPicker(type: 'photo' | 'video', target: typeof pickerTarget.value): void {
  pickerType.value = type;
  pickerTarget.value = target;
  showPicker.value = true;
}

function handlePickerSelect(value: string): void {
  if (pickerTarget.value === 'poster') {
    meta.value.posterUrl = value;
  } else if (pickerTarget.value === 'add-preview') {
    previewUrl.value = value;
  } else if (pickerTarget.value === 'edit-preview') {
    editEpForm.value.previewUrl = value;
  } else if (pickerTarget.value === 'add-stream') {
    streamUrl.value = value;
  } else if (pickerTarget.value === 'edit-stream') {
    editEpForm.value.streamUrl = value;
  }
  showPicker.value = false;
}

async function load(): Promise<void> {
  error.value = null;
  try {
    const t = await fetchTitle(props.titleId);
    title.value = t;
    episodes.value = [...t.episodes];
    meta.value = {
      displayName: t.displayName,
      seasonNumber: String(t.seasonNumber),
      seasonLabel: t.seasonLabel ?? '',
      description: t.description,
      originalReleaseDate: t.originalReleaseDate ?? '',
      episodesCount: t.episodesPlanned.count !== null ? String(t.episodesPlanned.count) : '',
      episodesOpen: t.episodesPlanned.open,
      visible: t.status !== 'hidden',
      posterUrl: t.posterUrl ?? '',
      genreIds: t.genres.map((g) => g.id),
      names: t.names.map((n) => ({ kind: (n.kind as AltKind) ?? 'other', name: n.name })),
    };
  } catch (e) {
    error.value = e instanceof Error ? e.message : 'Помилка завантаження';
  }
}

function toggleGenre(id: number): void {
  const i = meta.value.genreIds.indexOf(id);
  if (i >= 0) meta.value.genreIds.splice(i, 1);
  else meta.value.genreIds.push(id);
}
function addAltName(): void {
  meta.value.names.push({ kind: 'original', name: '' });
}
function removeAltName(i: number): void {
  meta.value.names.splice(i, 1);
}

async function saveMeta(): Promise<void> {
  metaError.value = null;
  metaOk.value = false;
  if (!String(meta.value.displayName).trim()) {
    metaError.value = 'Вкажіть назву';
    return;
  }
  busy.value = true;
  try {
    const countRaw = String(meta.value.episodesCount).trim();
    const posterLink = String(meta.value.posterUrl).trim();
    await updateTitle(props.titleId, {
      displayName: String(meta.value.displayName).trim(),
      description: String(meta.value.description).trim(),
      seasonNumber: Number(meta.value.seasonNumber) || 1,
      seasonLabel: String(meta.value.seasonLabel).trim() || null,
      status: meta.value.visible ? 'ongoing' : 'hidden',
      originalReleaseDate: meta.value.originalReleaseDate || null,
      genreIds: meta.value.genreIds,
      names: meta.value.names
        .filter((n) => String(n.name).trim())
        .map((n) => ({ kind: n.kind, name: String(n.name).trim() })),
      episodesPlanned: countRaw
        ? { count: Number(countRaw), open: meta.value.episodesOpen }
        : { count: null, open: false },
      posterUrl: posterLink || null,
    });
    metaOk.value = true;
    showEditModal.value = false;
    await load();
  } catch (e) {
    metaError.value = e instanceof Error ? e.message : 'Помилка збереження';
  } finally {
    busy.value = false;
  }
}

async function addEpisode(): Promise<void> {
  epError.value = null;
  const stream = String(streamUrl.value).trim();
  const video = String(videoUrl.value).trim();
  const fileId = String(tgFileId.value).trim();
  if (!stream && !video && !fileId) {
    epError.value = 'Вкажіть відео для сайту (пряме посилання) та/або джерело для бота (t.me / file_id)';
    return;
  }
  const hasLabel = String(epLabel.value).trim().length > 0;
  const numStr = String(epNumber.value).trim();
  const num = numStr === '' ? null : Number(numStr);
  if (!hasLabel && (num === null || !Number.isInteger(num))) {
    epError.value = 'Вкажіть номер серії або кастомну назву';
    return;
  }
  busy.value = true;
  try {
    await createEpisode(props.titleId, {
      number: hasLabel ? null : num,
      customLabel: hasLabel ? String(epLabel.value).trim() : null,
      streamUrl: stream || null,
      videoUrl: video || null,
      tgFileId: fileId || null,
      previewUrl: String(previewUrl.value).trim() || null,
    });
    epNumber.value = '';
    epLabel.value = '';
    streamUrl.value = '';
    videoUrl.value = '';
    tgFileId.value = '';
    previewUrl.value = '';
    await load();
  } catch (e) {
    epError.value = e instanceof Error ? e.message : 'Помилка додавання серії';
  } finally {
    busy.value = false;
  }
}

async function move(index: number, dir: -1 | 1): Promise<void> {
  const target = index + dir;
  if (target < 0 || target >= episodes.value.length) return;
  const arr = [...episodes.value];
  const a = arr[index];
  const b = arr[target];
  if (!a || !b) return;
  arr[index] = b;
  arr[target] = a;
  episodes.value = arr;
  await reorderEpisodes(
    props.titleId,
    arr.map((e) => e.id),
  ).catch((e) => (error.value = e instanceof Error ? e.message : 'Помилка порядку'));
}

async function removeEpisode(id: number): Promise<void> {
  await deleteEpisode(id).catch(() => {});
  episodes.value = episodes.value.filter((e) => e.id !== id);
}

// ── Edit episode modal ────────────────────────────────────
const editEp = ref<EpisodeItem | null>(null);
const editEpForm = ref({ number: '', label: '', streamUrl: '', videoUrl: '', tgFileId: '', previewUrl: '', publishedAt: '' });
const editEpError = ref<string | null>(null);

async function openEpisodeEdit(ep: EpisodeItem): Promise<void> {
  editEp.value = ep;
  editEpError.value = null;
  editEpForm.value = {
    number: ep.number != null ? String(ep.number) : '',
    label: ep.customLabel ?? '',
    streamUrl: '',
    videoUrl: '',
    tgFileId: '',
    previewUrl: ep.previewUrl ?? '',
    publishedAt: '',
  };

  try {
    const details = await getAdminEpisode(ep.id);
    editEpForm.value.streamUrl = details.streamUrl ?? '';
    editEpForm.value.videoUrl = details.videoUrl ?? '';
    editEpForm.value.tgFileId = details.tgFileId ?? '';
    editEpForm.value.previewUrl = details.previewUrl ?? '';
    // Convert ISO string → datetime-local format (YYYY-MM-DDTHH:mm)
    if (details.publishedAt) {
      const d = new Date(details.publishedAt);
      const pad = (n: number) => String(n).padStart(2, '0');
      editEpForm.value.publishedAt =
        `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
    }
  } catch (e) {
    console.error('Failed to load full episode details for editing:', e);
  }
}

async function saveEpisodeEdit(): Promise<void> {
  if (!editEp.value) return;
  editEpError.value = null;
  const f = editEpForm.value;
  const hasLabel = f.label.trim().length > 0;
  const numStr = f.number.trim();
  const num = numStr === '' ? null : Number(numStr);
  if (!hasLabel && (num === null || !Number.isInteger(num))) {
    editEpError.value = 'Вкажіть номер серії або кастомну назву';
    return;
  }

  // Convert datetime-local (local time, no TZ) → full ISO string with offset
  let publishedAt: string | null = null;
  if (f.publishedAt) {
    const d = new Date(f.publishedAt);
    if (!isNaN(d.getTime())) publishedAt = d.toISOString();
  }

  const patch: CreateEpisodeInput = {
    number: hasLabel ? null : num,
    customLabel: hasLabel ? f.label.trim() : null,
    streamUrl: f.streamUrl.trim() || null,
    videoUrl: f.videoUrl.trim() || null,
    tgFileId: f.tgFileId.trim() || null,
    previewUrl: f.previewUrl.trim() || null,
    publishedAt,
  };

  busy.value = true;
  try {
    await updateEpisode(editEp.value.id, patch);
    editEp.value = null;
    await load();
  } catch (e) {
    editEpError.value = e instanceof Error ? e.message : 'Помилка збереження';
  } finally {
    busy.value = false;
  }
}

// ── Poster upload logic ─────────────────────────────
const posterUploading = ref(false);
const posterUploadError = ref<string | null>(null);
const posterFileInput = ref<HTMLInputElement | null>(null);

function triggerPosterUpload(): void {
  posterFileInput.value?.click();
}

async function handlePosterFile(file: File | Blob): Promise<void> {
  posterUploading.value = true;
  posterUploadError.value = null;
  try {
    const label = `Постер: ${title.value?.displayName || 'Тайтл без назви'}`;
    const res = await uploadPhoto(file, label);
    meta.value.posterUrl = res.url;
  } catch (e) {
    posterUploadError.value = e instanceof Error ? e.message : 'Помилка завантаження постеру';
  } finally {
    posterUploading.value = false;
  }
}

function onPosterFileSelect(e: Event): void {
  const input = e.target as HTMLInputElement;
  const f = input.files?.[0];
  if (f) void handlePosterFile(f);
}

function onPosterPaste(e: ClipboardEvent): void {
  const text = e.clipboardData?.getData('text/plain')?.trim() || '';
  if (/^https?:\/\//i.test(text) && (text.includes('/posters/') || text.includes('/photos/'))) {
    e.preventDefault();
    meta.value.posterUrl = text;
    return;
  }
  const items = e.clipboardData?.items;
  if (!items) return;
  for (const item of items) {
    if (item.type.indexOf('image') !== -1) {
      const f = item.getAsFile();
      if (f) {
        e.preventDefault();
        void handlePosterFile(f);
        break;
      }
    }
  }
}

// ── Episode preview upload (Add form) ──────────────
const previewUploading = ref(false);
const previewUploadError = ref<string | null>(null);
const previewFileInput = ref<HTMLInputElement | null>(null);

function triggerPreviewUpload(): void {
  previewFileInput.value?.click();
}

async function handlePreviewFile(file: File | Blob): Promise<void> {
  previewUploading.value = true;
  previewUploadError.value = null;
  try {
    const epNum = epNumber.value ? ` серія ${epNumber.value}` : '';
    const label = `Прев'ю: ${title.value?.displayName || 'Тайтл'}${epNum}`;
    const res = await uploadPhoto(file, label);
    previewUrl.value = res.url;
  } catch (e) {
    previewUploadError.value = e instanceof Error ? e.message : 'Помилка завантаження прев’ю';
  } finally {
    previewUploading.value = false;
  }
}

function onPreviewFileSelect(e: Event): void {
  const input = e.target as HTMLInputElement;
  const f = input.files?.[0];
  if (f) void handlePreviewFile(f);
}

function onPreviewPaste(e: ClipboardEvent): void {
  const text = e.clipboardData?.getData('text/plain')?.trim() || '';
  if (/^https?:\/\//i.test(text) && (text.includes('/posters/') || text.includes('/photos/'))) {
    e.preventDefault();
    previewUrl.value = text;
    return;
  }
  const items = e.clipboardData?.items;
  if (!items) return;
  for (const item of items) {
    if (item.type.indexOf('image') !== -1) {
      const f = item.getAsFile();
      if (f) {
        e.preventDefault();
        void handlePreviewFile(f);
        break;
      }
    }
  }
}

// ── Episode preview upload (Edit form) ─────────────
const editPreviewUploading = ref(false);
const editPreviewUploadError = ref<string | null>(null);
const editPreviewFileInput = ref<HTMLInputElement | null>(null);

function triggerEditPreviewUpload(): void {
  editPreviewFileInput.value?.click();
}

async function handleEditPreviewFile(file: File | Blob): Promise<void> {
  editPreviewUploading.value = true;
  editPreviewUploadError.value = null;
  try {
    const epNum = editEpForm.value.number ? ` серія ${editEpForm.value.number}` : '';
    const label = `Прев'ю: ${title.value?.displayName || 'Тайтл'}${epNum}`;
    const res = await uploadPhoto(file, label);
    editEpForm.value.previewUrl = res.url;
  } catch (e) {
    editPreviewUploadError.value = e instanceof Error ? e.message : 'Помилка завантаження прев’ю';
  } finally {
    editPreviewUploading.value = false;
  }
}

function onEditPreviewFileSelect(e: Event): void {
  const input = e.target as HTMLInputElement;
  const f = input.files?.[0];
  if (f) void handleEditPreviewFile(f);
}

function onEditPreviewPaste(e: ClipboardEvent): void {
  const text = e.clipboardData?.getData('text/plain')?.trim() || '';
  if (/^https?:\/\//i.test(text) && (text.includes('/posters/') || text.includes('/photos/'))) {
    e.preventDefault();
    editEpForm.value.previewUrl = text;
    return;
  }
  const items = e.clipboardData?.items;
  if (!items) return;
  for (const item of items) {
    if (item.type.indexOf('image') !== -1) {
      const f = item.getAsFile();
      if (f) {
        e.preventDefault();
        void handleEditPreviewFile(f);
        break;
      }
    }
  }
}

async function searchGroup(): Promise<void> {
  if (String(groupQuery.value).trim().length < 3) {
    groupResults.value = [];
    return;
  }
  groupResults.value = (
    await adminSearchTitles(String(groupQuery.value).trim()).catch(() => [])
  ).filter((t) => t.id !== props.titleId);
}

async function link(otherId: number): Promise<void> {
  groupError.value = null;
  try {
    await groupTitle(props.titleId, otherId);
    groupResults.value = [];
    groupQuery.value = '';
    await load();
  } catch (e) {
    groupError.value = e instanceof Error ? e.message : 'Помилка групування';
  }
}

async function unlink(): Promise<void> {
  await ungroupTitle(props.titleId).catch(() => {});
  await load();
}

async function moveSeason(index: number, dir: number): Promise<void> {
  if (!title.value) return;
  const targetIndex = index + dir;
  if (targetIndex < 0 || targetIndex >= title.value.seasons.length) return;

  busy.value = true;
  error.value = null;

  // Clone and swap
  const list = [...title.value.seasons];
  const temp = list[index]!;
  list[index] = list[targetIndex]!;
  list[targetIndex] = temp;

  try {
    const order = list.map((s) => s.titleId);
    await reorderSeasons(props.titleId, order);
    await load();
  } catch (e) {
    error.value = e instanceof Error ? e.message : 'Помилка сортування сезонів';
  } finally {
    busy.value = false;
  }
}

onMounted(async () => {
  genres.value = await fetchGenres().catch(() => []);
  await load();
});
watch(() => props.titleId, load);
</script>

<template>
  <div v-if="title" class="editor">
    <header class="editor__head">
      <div>
        <h3>{{ title.displayName }}</h3>
        <span class="mono">{{ title.seasonLabel || 'Сезон ' + title.seasonNumber }} (#{{ title.id }})</span>
      </div>
      <button class="btn btn--sm" type="button" @click="showEditModal = true">📝 Редагувати метадані</button>
    </header>
    <p v-if="error" class="msg msg--err">{{ error }}</p>

    <!-- Edit Metadata Modal -->
    <div v-if="showEditModal" class="modal-backdrop" @click.self="showEditModal = false">
      <div class="modal-content">
        <header class="modal-header">
          <h3>Редагувати тайтл</h3>
          <button type="button" class="modal-close" @click="showEditModal = false">✕</button>
        </header>
        <div class="modal-body fields">
          <label class="field">
            <span>Назва для відображення</span>
            <input v-model="meta.displayName" />
          </label>
          <div class="row">
            <label class="field">
              <span>Сезон (номер)</span>
              <input v-model="meta.seasonNumber" type="number" />
            </label>
            <label class="field">
              <span>Назва сезону (напр. Фільм, OVA)</span>
              <input v-model="meta.seasonLabel" placeholder="Сезон 1" />
            </label>
          </div>
          <div class="row">
            <label class="field">
              <span>Дата оригіналу</span>
              <input v-model="meta.originalReleaseDate" type="date" />
            </label>
            <label class="field">
              <span>К-сть серій (порожньо = N/A)</span>
              <input v-model="meta.episodesCount" type="number" />
            </label>
          </div>
          <label class="field">
            <span>Опис</span>
            <textarea v-model="meta.description" rows="3" />
          </label>
          <div class="row">
            <label class="check">
              <input v-model="meta.episodesOpen" type="checkbox" /> «+» (із запасом)
            </label>
            <label class="check">
              <input v-model="meta.visible" type="checkbox" /> Видне користувачам
            </label>
          </div>
          <label class="field">
            <span>Пряме посилання на постер (t.me/… або пряме посилання)</span>
            <div class="input-with-upload">
              <input v-model="meta.posterUrl" placeholder="https://t.me/DaliBudeDub/13" @paste="onPosterPaste" />
              <button class="btn btn--upload" type="button" :disabled="posterUploading" @click="triggerPosterUpload">
                {{ posterUploading ? '☁ Завантаження…' : '☁ Завантажити / Вставити' }}
              </button>
              <button class="btn btn--upload" type="button" @click="openPicker('photo', 'poster')">
                📁 Обрати з R2
              </button>
              <input ref="posterFileInput" type="file" accept="image/*" class="hidden-file-input" @change="onPosterFileSelect" />
            </div>
            <p v-if="posterUploadError" class="err">{{ posterUploadError }}</p>
          </label>

          <div class="subblock">
            <div class="subblock__head">
              <span>Альтернативні назви</span>
              <button type="button" class="btn btn--ghost btn--sm" @click="addAltName">+ Додати</button>
            </div>
            <div v-for="(n, i) in meta.names" :key="i" class="altrow">
              <select v-model="n.kind">
                <option value="original">Оригінал</option>
                <option value="english">Англ.</option>
                <option value="ukrainian">Укр.</option>
                <option value="other">Інша</option>
              </select>
              <input v-model="n.name" placeholder="Назва" />
              <button type="button" class="btn--del" title="Видалити" @click="removeAltName(i)">✕</button>
            </div>
          </div>

          <div class="subblock">
            <span class="subblock__label">Жанри</span>
            <div class="chips">
              <button
                v-for="g in genres"
                :key="g.id"
                type="button"
                class="chip"
                :class="{ on: meta.genreIds.includes(g.id) }"
                @click="toggleGenre(g.id)"
              >
                {{ g.name }}
              </button>
            </div>
          </div>

          <p v-if="metaError" class="msg msg--err">{{ metaError }}</p>
          <p v-if="metaOk" class="msg msg--ok">✅ Збережено</p>
        </div>
        <div class="modal-footer">
          <button class="btn btn--ghost" type="button" @click="showEditModal = false">Закрити</button>
          <button class="btn" type="button" :disabled="busy" @click="saveMeta">Зберегти зміни</button>
        </div>
      </div>
    </div>

    <!-- Edit Episode Modal -->
    <div v-if="editEp" class="modal-backdrop" @click.self="editEp = null">
      <div class="modal-content">
        <header class="modal-header">
          <h3>Редагувати серію</h3>
          <button type="button" class="modal-close" @click="editEp = null">✕</button>
        </header>
        <div class="modal-body fields">
          <div class="row">
            <label class="field">
              <span>Номер (напр. 12)</span>
              <input v-model="editEpForm.number" type="number" />
            </label>
            <label class="field">
              <span>або кастомна назва</span>
              <input v-model="editEpForm.label" placeholder="OVA 1" />
            </label>
          </div>
          <label class="field">
            <span>Відео для сайту — новий UUID або пряме посилання</span>
            <div class="input-with-upload">
              <input v-model="editEpForm.streamUrl" placeholder="UUID зі «Сховище R2» або https://…mp4" />
              <button class="btn btn--upload" type="button" @click="openPicker('video', 'edit-stream')">
                📁 Обрати з R2
              </button>
            </div>
            <small class="field__hint">Залиште порожнім, щоб не змінювати.</small>
          </label>
          <label class="field">
            <span>Відео для бота — посилання на пост (t.me/…)</span>
            <input v-model="editEpForm.videoUrl" placeholder="https://t.me/dalibude_storage/7" />
            <small class="field__hint">Залиште порожнім, щоб не змінювати.</small>
          </label>
          <label class="field">
            <span>Telegram file_id (альтернатива для бота)</span>
            <input v-model="editEpForm.tgFileId" placeholder="BAACAgIAAx…" />
            <small class="field__hint">Залиште порожнім, щоб не змінювати.</small>
          </label>
          <label class="field">
