<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { fetchGenres } from '@/entities/genre/genre.api';
import { createGenre, deleteGenre } from '@/entities/admin/admin.api';
import type { Genre } from '@/shared/api/types';

const genres = ref<Genre[]>([]);
const name = ref('');
const slug = ref('');
const error = ref<string | null>(null);
const busy = ref(false);
const showAddModal = ref(false);

async function load(): Promise<void> {
  genres.value = await fetchGenres().catch(() => []);
}

function autoSlug(): void {
  if (!slug.value) {
    slug.value = name.value
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');
  }
}

async function add(): Promise<void> {
  error.value = null;
  if (!name.value.trim() || !slug.value.trim()) return;
  busy.value = true;
  try {
    const g = await createGenre(name.value.trim(), slug.value.trim());
    genres.value.push(g);
    genres.value.sort((a, b) => a.name.localeCompare(b.name));
    name.value = '';
    slug.value = '';
    showAddModal.value = false;
  } catch (e) {
    error.value = e instanceof Error ? e.message : 'Помилка';
  } finally {
    busy.value = false;
  }
}

async function remove(id: number): Promise<void> {
  await deleteGenre(id).catch(() => {});
  genres.value = genres.value.filter((g) => g.id !== id);
}

onMounted(load);
</script>

<template>
  <div class="genres">
    <div class="genres__actions">
      <button class="btn" type="button" @click="showAddModal = true">+ Створити жанр</button>
    </div>

    <!-- Modal for adding genre -->
    <div v-if="showAddModal" class="modal-backdrop" @click.self="showAddModal = false">
      <div class="modal-content">
        <header class="modal-header">
          <h3>Створити жанр</h3>
          <button type="button" class="modal-close" @click="showAddModal = false">✕</button>
        </header>
        <form class="modal-body form" @submit.prevent="add">
          <label class="field">
            <span>Назва (напр. Комедія)</span>
            <input v-model="name" placeholder="Комедія" @blur="autoSlug" />
          </label>
          <label class="field">
            <span>slug (напр. comedy)</span>
            <input v-model="slug" placeholder="comedy" />
          </label>
          <p v-if="error" class="genres__error msg msg--err">{{ error }}</p>
          <button class="btn" type="submit" :disabled="busy">Додати</button>
        </form>
      </div>
    </div>

    <ul class="genres__list">
      <li v-for="g in genres" :key="g.id">
        <span>{{ g.name }}</span>
        <span class="genres__slug mono">{{ g.slug }}</span>
        <button type="button" class="genres__del" @click="remove(g.id)">✕</button>
      </li>
    </ul>
  </div>
</template>

