<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import {
  deleteMedia,
  getMediaStatus,
  listMedia,
  updateMediaTimings,
  uploadMedia,
  type MediaAsset,
  type MediaJobStatus,
  // Photo API imports
  listPhotos,
  uploadPhoto,
  deletePhoto,
  type PhotoAsset,
} from '@/entities/admin/admin.api';

const mediaTab = ref<'video' | 'photo'>('video');

// Video HLS assets state
const assets = ref<MediaAsset[]>([]);
const loading = ref(true);
const loadError = ref<string | null>(null);
const videoSearchQuery = ref('');

// Video Upload form state
const file = ref<File | null>(null);
const label = ref('');
const uploading = ref(false); // my own upload is in flight
const sendProgress = ref(0); // browser → server upload %
const uploadError = ref<string | null>(null);
const lastUuid = ref<string | null>(null);
const copiedId = ref<string | null>(null);
const fileInput = ref<HTMLInputElement | null>(null);
const isVideoDragging = ref(false);

// Photo assets state
const photos = ref<PhotoAsset[]>([]);
const photosLoading = ref(true);
const photosLoadError = ref<string | null>(null);
const photoSearchQuery = ref('');

// Photo Upload form state
const photoFile = ref<File | Blob | null>(null);
const photoPreviewUrl = ref<string | null>(null);
const photoLabel = ref('');
const photoUploading = ref(false);
const photoSendProgress = ref(0);
const photoUploadError = ref<string | null>(null);
const photoLastAsset = ref<PhotoAsset | null>(null);
const photoFileInput = ref<HTMLInputElement | null>(null);
const isPhotoDragging = ref(false);

// Shared ingest job (transcode + R2 upload), polled so every admin sees it.
const status = ref<MediaJobStatus | null>(null);
let pollTimer: ReturnType<typeof setInterval> | undefined;

/** A job is running somewhere (mine or another admin's) → block new uploads. */
const busy = computed(() => uploading.value || (status.value?.active ?? false));
const othersBusy = computed(() => !uploading.value && (status.value?.active ?? false));

function phaseLabel(phase: MediaJobStatus['phase']): string {
  if (phase === 'transcoding') return 'Транскодування';
  if (phase === 'uploading') return 'Вивантаження в R2';
  return 'Фіналізація';
}

const filteredAssets = computed(() => {
  const q = videoSearchQuery.value.trim().toLowerCase();
  if (!q) return assets.value;
  return assets.value.filter((a) => {
    if (a.id.toLowerCase().includes(q)) return true;
    if (a.label && a.label.toLowerCase().includes(q)) return true;
    if (a.usages && a.usages.some((u) => 
      u.titleName.toLowerCase().includes(q) || 
      (u.seasonLabel && u.seasonLabel.toLowerCase().includes(q))
    )) return true;
    return false;
  });
});

const filteredPhotos = computed(() => {
  const q = photoSearchQuery.value.trim().toLowerCase();
  if (!q) return photos.value;
  return photos.value.filter((p) => {
    if (p.id.toLowerCase().includes(q)) return true;
    if (p.label && p.label.toLowerCase().includes(q)) return true;
    if (p.url.toLowerCase().includes(q)) return true;
    return false;
  });
});

async function load(silent = false): Promise<void> {
  if (!silent) loading.value = true;
  loadError.value = null;
  try {
    assets.value = await listMedia();
  } catch (e) {
    loadError.value = e instanceof Error ? e.message : 'Не вдалося завантажити список';
  } finally {
    loading.value = false;
  }
}

async function loadPhotos(silent = false): Promise<void> {
  if (!silent) photosLoading.value = true;
  photosLoadError.value = null;
  try {
    photos.value = await listPhotos();
  } catch (e) {
    photosLoadError.value = e instanceof Error ? e.message : 'Не вдалося завантажити список фото';
  } finally {
    photosLoading.value = false;
  }
}

async function pollStatus(): Promise<void> {
  try {
    const next = await getMediaStatus();
    const wasActive = status.value?.active ?? false;
    status.value = next;
    // Another admin's job just finished → refresh the list to show the new file.
    if (wasActive && !next.active && !uploading.value) await load(true);
  } catch {
    /* transient — keep polling */
  }
}

function onFileChange(e: Event): void {
  const input = e.target as HTMLInputElement;
  file.value = input.files?.[0] ?? null;
  uploadError.value = null;
  lastUuid.value = null;
}

function onVideoDrop(e: DragEvent): void {
  isVideoDragging.value = false;
  const dropped = e.dataTransfer?.files?.[0] ?? null;
  if (dropped) {
    file.value = dropped;
    uploadError.value = null;
    lastUuid.value = null;
  }
}

function clearSelectedFile(): void {
  file.value = null;
  uploadError.value = null;
  if (fileInput.value) fileInput.value.value = '';
}

function fmtSize(bytes: number): string {
  if (bytes === 0) return '0 B';
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
}

async function upload(): Promise<void> {
  if (!file.value || busy.value) return;
  uploadError.value = null;
  lastUuid.value = null;
  uploading.value = true;
  sendProgress.value = 0;
  try {
    const res = await uploadMedia(file.value, label.value, (p) => (sendProgress.value = p));
    lastUuid.value = res.id;
    label.value = '';
    file.value = null;
    if (fileInput.value) fileInput.value.value = '';
    await load(true);
  } catch (e) {
    uploadError.value =
      e instanceof Error ? e.message : 'Помилка завантаження';
  } finally {
    uploading.value = false;
    sendProgress.value = 0;
    await pollStatus();
  }
}

async function remove(asset: MediaAsset): Promise<void> {
  if (busy.value) return;
  const used = asset.episodeCount > 0 ? `\nВоно використовується у ${asset.episodeCount} сер.` : '';
  if (!confirm(`Видалити файл зі сховища?${used}`)) return;
  try {
    await deleteMedia(asset.id);
    assets.value = assets.value.filter((a) => a.id !== asset.id);
  } catch (e) {
    loadError.value = e instanceof Error ? e.message : 'Не вдалося видалити';
  }
}

// Photo file/paste methods
function onPhotoFileChange(e: Event): void {
  const input = e.target as HTMLInputElement;
  const f = input.files?.[0] ?? null;
  if (f) {
    photoFile.value = f;
    photoPreviewUrl.value = URL.createObjectURL(f);
    photoUploadError.value = null;
    photoLastAsset.value = null;
  }
}

function onPhotoDrop(e: DragEvent): void {
  isPhotoDragging.value = false;
  const f = e.dataTransfer?.files?.[0] ?? null;
  if (f) {
    photoFile.value = f;
    photoPreviewUrl.value = URL.createObjectURL(f);
    photoUploadError.value = null;
    photoLastAsset.value = null;
  }
}

function clearSelectedPhoto(): void {
  photoFile.value = null;
  if (photoPreviewUrl.value) {
    URL.revokeObjectURL(photoPreviewUrl.value);
    photoPreviewUrl.value = null;
  }
  if (photoFileInput.value) photoFileInput.value.value = '';
}

function handlePhotoPaste(e: ClipboardEvent): void {
  if (mediaTab.value !== 'photo') return;
  const text = e.clipboardData?.getData('text/plain')?.trim() || '';
  if (/^https?:\/\//i.test(text) && (text.includes('/posters/') || text.includes('/photos/'))) {
    return;
  }
  const items = e.clipboardData?.items;
  if (!items) return;
  for (const item of items) {
    if (item.type.indexOf('image') !== -1) {
      const pasted = item.getAsFile();
      if (pasted) {
        photoFile.value = pasted;
        photoPreviewUrl.value = URL.createObjectURL(pasted);
        photoUploadError.value = null;
        photoLastAsset.value = null;
        if (!photoLabel.value) {
          photoLabel.value = `З буфера обміну (${new Date().toLocaleTimeString('uk-UA')})`;
        }
        e.preventDefault();
        break;
      }
    }
  }
}

async function uploadPhotoAction(): Promise<void> {
  if (!photoFile.value || photoUploading.value) return;
  photoUploadError.value = null;
  photoLastAsset.value = null;
  photoUploading.value = true;
  photoSendProgress.value = 0;
  try {
    const res = await uploadPhoto(photoFile.value, photoLabel.value, (p) => {
      photoSendProgress.value = p;
    });
    photoLastAsset.value = res;
    photoLabel.value = '';
    photoFile.value = null;
    if (photoPreviewUrl.value) {
      URL.revokeObjectURL(photoPreviewUrl.value);
      photoPreviewUrl.value = null;
    }
    if (photoFileInput.value) photoFileInput.value.value = '';
    await loadPhotos(true);
  } catch (e) {
    photoUploadError.value = e instanceof Error ? e.message : 'Помилка завантаження фото';
  } finally {
    photoUploading.value = false;
    photoSendProgress.value = 0;
  }
}

async function removePhoto(photo: PhotoAsset): Promise<void> {
  if (photoUploading.value) return;
  if (!confirm('Видалити фото зі сховища?')) return;
  try {
    await deletePhoto(photo.id);
    photos.value = photos.value.filter((p) => p.id !== photo.id);
  } catch (e) {
    photosLoadError.value = e instanceof Error ? e.message : 'Не вдалося видалити фото';
  }
}

async function copy(val: string): Promise<void> {
  try {
    await navigator.clipboard.writeText(val);
    copiedId.value = val;
    setTimeout(() => (copiedId.value = null), 1600);
  } catch {
    /* clipboard unavailable */
  }
}

function fmtDuration(s: number): string {
  const total = Math.round(s);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const sec = total % 60;
  const pad = (n: number) => String(n).padStart(2, '0');
  return h > 0 ? `${h}:${pad(m)}:${pad(sec)}` : `${m}:${pad(sec)}`;
}

function fmtDate(iso: string): string {
  return new Date(iso).toLocaleString('uk-UA', { dateStyle: 'medium', timeStyle: 'short' });
}

// ── Timings editor ────────────────────────────────────────
/** ID of the asset currently showing the timing form. */
const timingsEditId = ref<string | null>(null);
/** Form values (HH:MM:SS strings, empty = null). */
const timingsForm = ref({ openingStart: '', openingEnd: '', endingStart: '', endingEnd: '' });
const timingsSaving = ref(false);
const timingsError = ref<string | null>(null);

/** Converts seconds (number | null) → HH:MM:SS string (empty string when null). */
function secsToHms(s: number | null): string {
  if (s === null || s === undefined) return '';
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = s % 60;
  const p = (n: number) => String(n).padStart(2, '0');
  return `${p(h)}:${p(m)}:${p(sec)}`;
}

/** Parses "HH:MM:SS" or "MM:SS" → seconds (number), empty string → null. */
function hmsToSecs(v: string): number | null {
  const s = v.trim();
  if (!s) return null;
  const parts = s.split(':').map(Number);
  if (parts.some(isNaN)) return null;
  if (parts.length === 3) return parts[0]! * 3600 + parts[1]! * 60 + parts[2]!;
  if (parts.length === 2) return parts[0]! * 60 + parts[1]!;
  return parts[0] ?? null;
}

function openTimingsForm(asset: MediaAsset): void {
  timingsEditId.value = asset.id;
  timingsError.value = null;
  timingsForm.value = {
    openingStart: secsToHms(asset.openingStartS),
    openingEnd: secsToHms(asset.openingEndS),
    endingStart: secsToHms(asset.endingStartS),
    endingEnd: secsToHms(asset.endingEndS),
  };
}

function closeTimingsForm(): void {
  timingsEditId.value = null;
  timingsError.value = null;
}

async function saveTimings(): Promise<void> {
  if (!timingsEditId.value) return;
  timingsError.value = null;
  timingsSaving.value = true;
  try {
    await updateMediaTimings(timingsEditId.value, {
      openingStartS: hmsToSecs(timingsForm.value.openingStart),
      openingEndS: hmsToSecs(timingsForm.value.openingEnd),
      endingStartS: hmsToSecs(timingsForm.value.endingStart),
      endingEndS: hmsToSecs(timingsForm.value.endingEnd),
    });
    closeTimingsForm();
    await load(true);
  } catch (e) {
    timingsError.value = e instanceof Error ? e.message : 'Помилка збереження таймінгів';
  } finally {
    timingsSaving.value = false;
  }
}

onMounted(() => {
  void load();
  void loadPhotos();
  void pollStatus();
  pollTimer = setInterval(() => void pollStatus(), 2000);
  window.addEventListener('paste', handlePhotoPaste);
});
onBeforeUnmount(() => {
  if (pollTimer) clearInterval(pollTimer);
  window.removeEventListener('paste', handlePhotoPaste);
});
</script>

<template>
  <div class="media">
    <div class="media__subtabs">
      <button :class="{ on: mediaTab === 'video' }" @click="mediaTab = 'video'">Відео HLS</button>
      <button :class="{ on: mediaTab === 'photo' }" @click="mediaTab = 'photo'">Фото / Зображення</button>
    </div>

    <!-- Video HLS tab -->
    <div v-if="mediaTab === 'video'" class="media__tab-content">
      <!-- Upload -->
      <section class="card">
        <h4 class="card__title">Завантажити відео на R2</h4>
        <p class="card__hint">
          Файл транскодується у HLS-сегменти й вивантажується у Cloudflare R2. Отриманий UUID
          вставте в поле «Відео для сайту» під час додавання серії.
        </p>

        <label class="field">
          <span>Підказка (щоб упізнати файл) — напр. «Наруто · S1E1»</span>
          <input v-model="label" :disabled="busy" placeholder="Наруто · Сезон 1 · Серія 1" />
        </label>

        <div class="field">
          <span>Відеофайл (mp4, mkv, mov…)</span>
          <div 
            class="video-dropzone" 
            :class="{ 'has-file': file, 'is-dragging': isVideoDragging }"
            @dragover.prevent="isVideoDragging = true"
            @dragenter.prevent="isVideoDragging = true"
            @dragleave.prevent="isVideoDragging = false"
            @drop.prevent="onVideoDrop"
          >
            <div v-if="file" class="video-preview-container">
              <div class="video-preview-info">
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="video-icon">
                  <polygon points="23 7 16 12 23 17 23 7"></polygon>
                  <rect x="1" y="5" width="15" height="14" rx="2" ry="2"></rect>
                </svg>
                <div class="video-meta">
                  <span class="video-filename">{{ file.name }}</span>
                  <span class="video-filesize">{{ fmtSize(file.size) }}</span>
                </div>
              </div>
              <button class="btn-clear-video" type="button" @click="clearSelectedFile" title="Очистити вибір">✕</button>
            </div>
            <label v-else class="video-file-label">
              <span>Виберіть відеофайл або перетягніть його сюди</span>
              <input ref="fileInput" type="file" accept="video/*" :disabled="busy" @change="onFileChange" />
            </label>
          </div>
        </div>

        <div v-if="uploading" class="progress" role="progressbar" :aria-valuenow="sendProgress">
          <div
            class="progress__bar"
            :style="{ width: (sendProgress < 100 ? sendProgress : (status?.percent ?? 100)) + '%' }"
          ></div>
          <span class="progress__label">
            <template v-if="sendProgress < 100">Надсилання на сервер… {{ sendProgress }}%</template>
            <template v-else>Обробка на сервері… {{ status?.percent ?? 0 }}% (деталі нижче)</template>
          </span>
        </div>

        <p v-else-if="othersBusy" class="msg msg--warn">
          ⏳ Інший адміністратор завантажує відео. Нове завантаження буде доступне після завершення.
        </p>

        <p v-if="uploadError" class="msg msg--err">{{ uploadError }}</p>

        <div v-if="lastUuid" class="ok">
          <span class="ok__check">✓</span>
          <div class="ok__body">
            <span>Готово. UUID:</span>
            <button class="uuid" type="button" @click="copy(lastUuid)">
              <code>{{ lastUuid }}</code>
              <span class="uuid__copy">{{ copiedId === lastUuid ? 'Скопійовано' : 'Копіювати' }}</span>
            </button>
          </div>
        </div>

        <button class="btn btn--wide" type="button" :disabled="!file || busy" @click="upload">
          {{ uploading ? 'Завантаження…' : othersBusy ? 'Зайнято іншим завантаженням…' : 'Завантажити' }}
        </button>
      </section>

      <!-- List -->
      <section class="card">
        <h4 class="card__title">Файли у сховищі ({{ assets.length }})</h4>
        <input v-model="videoSearchQuery" class="search media-search" placeholder="Пошук по назві, UUID або тайтлу…" />

        <!-- Shared ingest banner — visible to every admin while a job runs -->
        <div v-if="status?.active" class="job">
          <div class="job__head">
            <span class="job__spinner" aria-hidden="true"></span>
            <span class="job__label">{{ status.label || 'Відео без підказки' }}</span>
            <span class="job__phase">{{ phaseLabel(status.phase) }}</span>
          </div>
          <div class="progress">
            <div class="progress__bar" :style="{ width: status.percent + '%' }"></div>
            <span class="progress__label">
              {{ status.percent }}%<template v-if="status.phase === 'uploading' && status.totalSegments">
                · {{ status.uploadedSegments }}/{{ status.totalSegments }} сегм.</template>
            </span>
          </div>
        </div>

        <p v-if="loading && assets.length === 0" class="card__hint">Завантаження…</p>
        <p v-else-if="loadError" class="msg msg--err">{{ loadError }}</p>
        <p v-else-if="assets.length === 0" class="card__hint">Ще немає завантажених файлів.</p>

        <ul v-else class="list">
          <li v-for="a in filteredAssets" :key="a.id" class="row">
            <div class="row__main">
              <span class="row__label">{{ a.label || 'Без підказки' }}</span>
              <button class="uuid uuid--sm" type="button" @click="copy(a.id)">
                <code>{{ a.id }}</code>
                <span class="uuid__copy">{{ copiedId === a.id ? '✓' : '⧉' }}</span>
              </button>
            </div>
            <div class="row__meta">
              <span>{{ a.segmentCount }} сегм.</span>
              <span>· {{ fmtDuration(a.durationS) }}</span>
              <span class="row__date">· {{ fmtDate(a.createdAt) }}</span>
            </div>
            <div v-if="a.usages && a.usages.length > 0" class="row__usages">
              <span class="row__used">Використовується в:</span>
              <span v-for="(u, i) in a.usages" :key="i" class="row__usage-item">
                {{ u.titleName }}
                <template v-if="u.seasonNumber > 1 || u.seasonLabel">
                  ({{ u.seasonLabel || 'Сезон ' + u.seasonNumber }})
                </template>
                <template v-if="u.episodeNumber || u.customLabel">
                  — {{ u.customLabel || 'Серія ' + u.episodeNumber }}
                </template>
              </span>
            </div>
            <!-- Timings badges -->
            <div v-if="a.openingStartS !== null || a.endingStartS !== null" class="row__timings">
              <span v-if="a.openingStartS !== null && a.openingEndS !== null" class="row__timing-badge row__timing-badge--op">
                ▷ Опенінг: {{ secsToHms(a.openingStartS) }} – {{ secsToHms(a.openingEndS) }}
              </span>
              <span v-if="a.endingStartS !== null && a.endingEndS !== null" class="row__timing-badge row__timing-badge--end">
                ⏹ Ендінг: {{ secsToHms(a.endingStartS) }} – {{ secsToHms(a.endingEndS) }}
              </span>
            </div>
            <div class="row__actions">
              <button
                class="row__timing-btn"
                type="button"
                :disabled="busy"
                :title="timingsEditId === a.id ? 'Закрити таймінги' : 'Редагувати таймінги опенінга/ендінга'"
                @click="timingsEditId === a.id ? closeTimingsForm() : openTimingsForm(a)"
              >
                <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
                {{ timingsEditId === a.id ? '✕' : 'Таймінги' }}
              </button>
              <button class="row__del" type="button" :disabled="busy" title="Видалити зі сховища" @click="remove(a)">✕</button>
            </div>

            <!-- Inline timings form -->
            <div v-if="timingsEditId === a.id" class="row__timings-form">
              <div class="timings-grid">
                <div class="timings-group">
                  <span class="timings-group__label">Опенінг</span>
                  <div class="timings-group__fields">
                    <label class="timings-field">
                      <span>Початок</span>
                      <input
                        v-model="timingsForm.openingStart"
                        type="text"
                        placeholder="00:00:00"
                        pattern="\d{1,2}:\d{2}:\d{2}"
                        maxlength="8"
                      />
                    </label>
                    <label class="timings-field">
                      <span>Кінець</span>
                      <input
                        v-model="timingsForm.openingEnd"
                        type="text"
                        placeholder="00:00:00"
                        pattern="\d{1,2}:\d{2}:\d{2}"
                        maxlength="8"
                      />
                    </label>
                  </div>
                </div>
                <div class="timings-group">
                  <span class="timings-group__label">Ендінг</span>
                  <div class="timings-group__fields">
                    <label class="timings-field">
                      <span>Початок</span>
                      <input
                        v-model="timingsForm.endingStart"
                        type="text"
                        placeholder="00:00:00"
                        pattern="\d{1,2}:\d{2}:\d{2}"
                        maxlength="8"
                      />
                    </label>
                    <label class="timings-field">
                      <span>Кінець</span>
                      <input
                        v-model="timingsForm.endingEnd"
                        type="text"
                        placeholder="00:00:00"
                        pattern="\d{1,2}:\d{2}:\d{2}"
                        maxlength="8"
                      />
                    </label>
                  </div>
                </div>
              </div>
              <p v-if="timingsError" class="msg msg--err">{{ timingsError }}</p>
              <p class="timings-hint">Формат ГГ:ХХ:СС, наприклад 00:01:30. Залиште порожнім щоб прибрати таймінг.</p>
              <div class="timings-actions">
                <button class="btn btn--sm" type="button" :disabled="timingsSaving" @click="saveTimings">
                  {{ timingsSaving ? 'Збереження…' : 'Зберегти' }}
                </button>
                <button class="btn btn--sm btn--ghost" type="button" @click="closeTimingsForm">Скасувати</button>
              </div>
            </div>
          </li>
        </ul>
      </section>
    </div>

    <!-- Photo/Images tab -->
    <div v-else-if="mediaTab === 'photo'" class="media__tab-content">
      <!-- Upload Photo -->
